use LabwcSecurityAction::Client;
use LabwcSecurityAction::Root;

has role => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

sub run {
    my ($self, @argv) = @_;

    if ($self->role() eq 'client') {
        return LabwcSecurityAction::Client->new()->run(@argv);
    }
    if ($self->role() eq 'root') {
        return LabwcSecurityAction::Root->new()->run(@argv);
    }
    print STDERR "fatal: invalid Labwc security action role\n";
    return 1;
}

