package LabwcNetworkScanAction::CLI;

use strict;
use warnings;

use Moo;
use MooX::Options
  protect_argv => 0,
  flavour => [qw(require_order no_auto_abbrev)];
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(Str);

use LabwcNetworkScanAction::Client;
use LabwcNetworkScanAction::Root;

has role => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

sub run {
    my ($self, @argv) = @_;

    return LabwcNetworkScanAction::Client->new()->run(@argv)
        if $self->role() eq 'client';
    return LabwcNetworkScanAction::Root->new()->run(@argv)
        if $self->role() eq 'root';

    print STDERR "fatal: invalid Labwc network scan action role\n";
    return 1;
}

1;

package LabwcNetworkControlAction::CLI;

use strict;
