use Moo;
use MooX::Options
  protect_argv => 0,
  flavour => [qw(require_order no_auto_abbrev)];
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(Str);

use LabwcNetworkControlAction::Client;
use LabwcNetworkControlAction::Root;

has role => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

sub run {
    my ($self, @argv) = @_;

    return LabwcNetworkControlAction::Client->new()->run(@argv)
        if $self->role() eq 'client';
    return LabwcNetworkControlAction::Root->new()->run(@argv)
        if $self->role() eq 'root';

    print STDERR "fatal: invalid Labwc network control action role\n";
    return 1;
}

1;

package LabwcSecurityAction::CLI;

use strict;
use warnings;

use Moo;
use MooX::Options
  protect_argv => 0,
  flavour => [qw(require_order no_auto_abbrev)];
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(Str);

use LabwcSecurityAction::Client;
use LabwcSecurityAction::Root;

has role => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

sub run {
    my ($self, @argv) = @_;

    if ($self->role() eq 'client') {
        return LabwcSecurityAction::Client->new()->run(@argv);
    }
    if ($self->role() eq 'root') {
        return LabwcSecurityAction::Root->new()->run(@argv);
    }
    print STDERR "fatal: invalid Labwc security action role\n";
    return 1;
}

1;

