validate_local_file() {
  requested_file=$1
  case "$requested_file" in
    /*) ;;
    *) fatal "local file path must be absolute" ;;
  esac
  case "$requested_file" in
    *'
'*) fatal "local file path cannot contain newlines" ;;
  esac
  [ ! -L "$requested_file" ] ||
    fatal "local file symlinks are not allowed"
  resolved_file=$(readlink -f -- "$requested_file") ||
    fatal "unable to resolve local file: $requested_file"
