}

validate_samsung_model() {
  samsung_model=$1
  case "$samsung_model" in
    ''|*[!ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-]*)
      fatal "Samsung model must contain only uppercase letters, digits, and hyphens"
      ;;
  esac
  [ "${#samsung_model}" -ge 4 ] && [ "${#samsung_model}" -le 32 ] ||
    fatal "Samsung model must contain between 4 and 32 characters"
}

validate_samsung_region() {
  samsung_region=$1
  case "$samsung_region" in
    ''|*[!ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789]*)
      fatal "Samsung region CSC must contain only uppercase letters and digits"
      ;;
  esac
  [ "${#samsung_region}" -ge 3 ] && [ "${#samsung_region}" -le 8 ] ||
    fatal "Samsung region CSC must contain between 3 and 8 characters"
}

validate_samsung_firmware_directory_syntax() {
  firmware_directory=$1
  case "$firmware_directory" in
    /*) ;;
    *) fatal "Samsung firmware directory must be an absolute path" ;;
  esac
  case "$firmware_directory" in
    *'
'*) fatal "Samsung firmware directory cannot contain newlines" ;;
  esac
  [ "${#firmware_directory}" -le 1024 ] ||
    fatal "Samsung firmware directory is too long"
}

