  requested_action=$1
  shift

  case "$requested_action" in
    server-status|start-server|repair-server|stop-server|reconnect-usb|reconnect-offline|wait-any-device|list-devices|diagnose-devices|adb-version|host-features|mdns-services|disconnect-all|fastboot-list)
