      validate_endpoint "$1"
      validate_pairing_code "$2"
      ;;
    connect-wireless|disconnect-wireless)
      [ "$#" -eq 1 ] || fatal "${requested_action} requires one endpoint"
      validate_endpoint "$1"
      ;;
