    for (1 .. 10) {
        if (!$self->port_in_use) {
            $self->clear_marker;
            return 1;
        }
        sleep 1;
    }
    return 0;
}

sub stop {
    my ($self) = @_;
    if (!$self->port_in_use) {
        $self->clear_marker;
        print "ADB server is already stopped.\n";
        return 0;
    }
