            and fail("managed Samsung firmware manifest must contain one $key");
        validate_manifest_scalar($value, $key);
        $values{$key} = $value;
    }
    return \%values;
}

sub value {
    my ($self, $manifest, $key) = @_;
    require_value(ref($manifest) eq 'HASH', 'managed Samsung firmware manifest is invalid');
