package AndroidADB::ADB::Transfer;

use strict;
use warnings;

use File::Basename qw(basename);
use File::Spec;
use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(Object);

use AndroidADB::Validation qw(
  fail
  require_value
  validate_local_file
  validate_remote_path
  validate_serial
);

has config => (
    is       => 'ro',
    isa      => Object,
    required => 1,
);

has command => (
    is       => 'ro',
    isa      => Object,
    required => 1,
);

has device => (
    is       => 'ro',
    isa      => Object,
    required => 1,
);

