  device_count=0
  ready_count=0
  unauthorized_count=0
  offline_count=0
  permission_count=0
  while IFS= read -r device_line; do
    case "$device_line" in
      ''|'List of devices attached'*) continue ;;
    esac
    device_count=$((device_count + 1))
    case "$device_line" in
      *"no permissions"*)
        device_status=no-permissions
        ;;
      *)
        device_status=$(printf '%s\n' "$device_line" | awk '{ print $2 }')
        ;;
    esac
    case "$device_status" in
      no-permissions) permission_count=$((permission_count + 1)) ;;
      unauthorized) unauthorized_count=$((unauthorized_count + 1)) ;;
      offline) offline_count=$((offline_count + 1)) ;;
      device) ready_count=$((ready_count + 1)) ;;
    esac
  done <<EOF
$devices_output
EOF

  printf '\nSummary: total=%s ready=%s unauthorized=%s offline=%s permission-errors=%s\n' \
    "$device_count" "$ready_count" "$unauthorized_count" "$offline_count" "$permission_count"
  [ "$device_count" -gt 0 ] || printf '%s\n' \
    'No Android transports are visible. Check the data cable, USB mode, Developer Options, USB debugging, and wireless endpoint.'
  [ "$unauthorized_count" -eq 0 ] || printf '%s\n' \
    'Unauthorized devices must be unlocked and approved at the RSA debugging prompt.'
  [ "$offline_count" -eq 0 ] || printf '%s\n' \
    'Offline transports can often be recovered with Reconnect Offline Devices or Repair / Restart ADB Server.'
  [ "$permission_count" -eq 0 ] || printf '%s\n' \
    'Permission errors require plugdev membership, a fresh login, and loaded Android udev rules.'
}

list_devices_for_menu() {
  devices_output=$(capture_adb_devices)
  printf '%s\n' "$devices_output" |
    awk '
      /^List of devices attached/ || !NF { next }
      {
        serial = $1
        state = $2
        if (index($0, "no permissions") > 0) {
          state = "no-permissions"
        }
        model = ""
        for (field = 3; field <= NF; field++) {
          if ($field ~ /^model:/) {
            model = substr($field, 7)
          }
        }
        if (model != "") {
          printf "%s [%s] %s\n", serial, state, model
        } else {
          printf "%s [%s]\n", serial, state
        }
      }
    '
}

list_fastboot_devices_for_menu() {
  timeout \
    --signal=TERM \
    --kill-after=2s \
    12s \
    "$FASTBOOT" devices -l |
    awk 'NF { printf "%s [fastboot]", $1; for (field = 2; field <= NF; field++) printf " %s", $field; printf "\n" }'
}

