run_in_terminal() {
  action=$1
  shift

  printf '\n=== Android Debug Bridge: %s ===\n\n' "$action"
  set +e
  run_action "$action" "$@"
  action_status=$?
  set -e

  printf '\n=== Action finished with status %s ===\n' "$action_status"
  notify_action_result "$action_status" "$action"
  if [ -t 0 ]; then
    printf 'Press Enter to close this terminal...'
    IFS= read -r _ || true
  fi
  exit "$action_status"
}

