        or fail("unable to finalize managed Android output: $!");
    return $final_path;
}

sub write_text {
    my ($self, $path, $content) = @_;
    $self->_require_managed_path($path);
    require_value(
        defined($content) && !ref($content),
        'managed Android output content is invalid',
    );
