from __future__ import annotations

import hashlib
import re
import sys
from pathlib import Path

repo = Path.cwd()


def manifest(path: Path, function: str) -> list[str]:
    text = path.read_text(encoding="utf-8")
    match = re.search(
        rf"^{re.escape(function)}\(\) \{{\n\s*cat <<'EOF'\n(.*?)^EOF\n\}}",
        text,
        re.MULTILINE | re.DOTALL,
    )
    if not match:
        raise AssertionError(f"manifest function not found: {path}:{function}")
    entries = [line.strip() for line in match.group(1).splitlines() if line.strip()]
    if len(entries) != len(set(entries)):
        raise AssertionError(f"duplicate manifest entry: {path}:{function}")
    return entries


def package_name(relative: Path) -> str:
    name = relative.name
    if name.endswith(".tmpl"):
        name = name[:-5]
    if name.endswith(".pm"):
        name = name[:-3]
    return "::".join((*relative.parts[:-1], name))


def audit_tree(label: str, root: Path, expected_manifest: list[str], include_templates: bool = False) -> dict[str, Path]:
    paths = sorted(
        p.relative_to(root)
        for p in root.rglob("*.pm")
        if p.is_file()
    )
    if include_templates:
        paths.extend(sorted(p.relative_to(root) for p in root.rglob("*.pm.tmpl") if p.is_file()))
    actual = [p.as_posix() for p in paths]
    expected = sorted(expected_manifest)
    if sorted(actual) != expected:
        raise AssertionError(
            f"{label} manifest mismatch\nexpected={expected}\nactual={sorted(actual)}"
        )

    packages: dict[str, Path] = {}
    for relative in paths:
        source = root / relative
        text = source.read_text(encoding="utf-8")
        expected_package = package_name(relative)
        match = re.search(r"^package\s+([A-Za-z_]\w*(?:::\w+)*)\s*;", text, re.MULTILINE)
        if not match:
            raise AssertionError(f"{label} has no package declaration: {source}")
        if match.group(1) != expected_package:
            raise AssertionError(
                f"{label} package path mismatch: {source}: {match.group(1)} != {expected_package}"
            )
        packages[expected_package] = source

    for package, source in packages.items():
        text = source.read_text(encoding="utf-8")
        for imported in re.findall(
            r"^use\s+((?:ManagedNetwork|AndroidADB|LabwcNetworkScanAction)(?:::\w+)*)\b",
            text,
            re.MULTILINE,
        ):
            if imported not in packages:
                raise AssertionError(f"{label} missing internal import {imported} used by {source}")
    return packages

network_script = repo / "d-i/forky/scripts/late/network.sh"
components = repo / "d-i/forky/scripts/desktop/components.sh"
managed_root = repo / "d-i/forky/hooks/shared/target/usr/lib/perl5/site_perl/managed-network"
adb_root = repo / "d-i/forky/hooks/role/desktop/target/usr/local/lib/perl5/site_perl/labwc-adb"
scan_root = repo / "d-i/forky/hooks/role/desktop/target/usr/local/lib/perl5/site_perl/labwc-network-scan-action"

managed = audit_tree(
    "ManagedNetwork",
    managed_root,
    manifest(network_script, "managed_network_perl_modules"),
)
adb = audit_tree(
    "AndroidADB",
    adb_root,
    manifest(components, "desktop_labwc_adb_perl_modules"),
)
scan_manifest = manifest(components, "desktop_labwc_network_scan_action_perl_modules")
scan = audit_tree(
    "LabwcNetworkScanAction",
    scan_root,
    [*scan_manifest, "LabwcNetworkScanAction/Root.pm.tmpl"],
    include_templates=True,
)

scan_render = components.read_text(encoding="utf-8")
if not re.search(
    r"desktop_render_role_target_template\s+\n\s*usr/local/lib/perl5/site_perl/labwc-network-scan-action/LabwcNetworkScanAction/Root\.pm\.tmpl\s+\n\s*/usr/local/lib/perl5/site_perl/labwc-network-scan-action/LabwcNetworkScanAction/Root\.pm",
    scan_render,
):
    raise AssertionError("LabwcNetworkScanAction Root template render contract is missing")

runners = {
    repo / "d-i/forky/hooks/shared/target/usr/local/libexec/managed-network-run": (
        "/usr/lib/perl5/site_perl/managed-network",
        "ManagedNetwork::CLI",
    ),
    repo / "d-i/forky/hooks/role/desktop/target/usr/local/bin/labwc-adb-action": (
        "/usr/local/lib/perl5/site_perl/labwc-adb",
        "AndroidADB::CLI",
    ),
    repo / "d-i/forky/hooks/role/desktop/target/usr/local/bin/labwc-network-scan-action": (
        "/usr/local/lib/perl5/site_perl/labwc-network-scan-action",
        "LabwcNetworkScanAction::Client",
    ),
    repo / "d-i/forky/hooks/role/desktop/target/usr/local/libexec/labwc-network-scan-action-root.tmpl": (
        "/usr/local/lib/perl5/site_perl/labwc-network-scan-action",
        "LabwcNetworkScanAction::Root",
    ),
}
for runner, (root, package) in runners.items():
    text = runner.read_text(encoding="utf-8")
    if f"use lib '{root}';" not in text and root not in text:
        raise AssertionError(f"runner has wrong module root: {runner}")
    if not re.search(rf"^use\s+{re.escape(package)}\s*;", text, re.MULTILINE):
        raise AssertionError(f"runner has wrong top-level package: {runner}")

apparmor = (repo / "d-i/forky/hooks/shared/target/etc/apparmor.d/managed-desktop-wrappers").read_text(encoding="utf-8")
for path in (
    "/usr/local/lib/perl5/site_perl/labwc-adb/** r,",
    "/usr/local/lib/perl5/site_perl/labwc-network-scan-action/** r,",
    "/usr/local/libexec/labwc-network-scan-action-root rix,",
