bin_files = [p for p in (repo / "d-i/forky/hooks").rglob("target/usr/local/bin/*") if p.is_file()]
libexec_files = [p for p in (repo / "d-i/forky/hooks").rglob("target/usr/local/libexec/*") if p.is_file()]
libexec_digests = {}
for path in libexec_files:
    digest = hashlib.sha256(path.read_bytes()).digest()
