package SyntheticLayout;

use strict;
use warnings;

use Cwd qw(abs_path);
use File::Spec ();

our ($ROOT, $PREFIX, $PRIMARY, $MODE, $EXPECTED_INC, @SERVED);

sub import {
    $ROOT = abs_path($ENV{SYNTHETIC_MODULE_ROOT} // q{})
        or die "SyntheticLayout requires a readable SYNTHETIC_MODULE_ROOT\n";
    $PREFIX = $ENV{SYNTHETIC_MODULE_PREFIX} // q{};
    $PRIMARY = $ENV{SYNTHETIC_PRIMARY_MODULE} // q{};
    $MODE = $ENV{SYNTHETIC_ROOT_MODE} // q{};
    $EXPECTED_INC = $ENV{SYNTHETIC_EXPECTED_INC} // q{};

    $PREFIX ne q{} or die "SyntheticLayout requires SYNTHETIC_MODULE_PREFIX\n";
    $PRIMARY ne q{} or die "SyntheticLayout requires SYNTHETIC_PRIMARY_MODULE\n";
    ($MODE eq 'canonical' || $MODE eq 'literal')
        or die "SyntheticLayout has an unsupported root mode\n";
    $MODE ne 'literal' || $EXPECTED_INC ne q{}
        or die "SyntheticLayout requires SYNTHETIC_EXPECTED_INC for literal mode\n";

    unshift @INC, sub {
        my ($hook, $requested) = @_;
        return if index($requested, $PREFIX) != 0;

        if ($MODE eq 'canonical') {
            my $found = 0;
            for my $entry (@INC) {
                next if ref $entry;
                my $resolved = abs_path($entry);
                if (defined($resolved) && $resolved eq $ROOT) {
                    $found = 1;
                    last;
                }
            }
            $found or die "SyntheticLayout did not observe the expected FindBin root for $requested\n";
        }
        else {
            grep { !ref($_) && $_ eq $EXPECTED_INC } @INC
                or die "SyntheticLayout did not observe the expected literal root for $requested\n";
        }

        $requested !~ m{(?:^|/)\.\.(?:/|$)}
            or die "SyntheticLayout rejected an unsafe module request\n";
        my $source = File::Spec->catfile($ROOT, split m{/}, $requested);
        -f $source or die "SyntheticLayout source is missing: $source\n";
        open my $fh, '<', $source
            or die "SyntheticLayout cannot read $source: $!\n";
        push @SERVED, $requested;
        return $fh;
    };
}

CHECK {
    if ($MODE eq 'canonical') {
        my $loaded = $INC{$PRIMARY} // q{};
        my $loaded_path = abs_path($loaded);
        my $expected_path = abs_path(File::Spec->catfile($ROOT, split m{/}, $PRIMARY));
        defined($loaded_path) && defined($expected_path) && $loaded_path eq $expected_path
            or die "SyntheticLayout loaded $PRIMARY outside its synthetic FindBin root\n";
    }
    elsif ($MODE eq 'literal') {
        grep { $_ eq $PRIMARY } @SERVED
            or die "SyntheticLayout did not serve $PRIMARY from the synthetic literal root\n";
    }
}

1;
